import type { OrgId } from "@/types/common";
import type { Subscription, WorkspaceLockReason } from "@/types/billing";

/** Thrown when a member writes to a workspace that is read-only. */
export class WorkspaceLockedError extends Error {
  readonly code = "plan_limit_exceeded";

  constructor(
    readonly orgId: OrgId,
    readonly reason: WorkspaceLockReason,
  ) {
    super(`Workspace is read-only (${reason}). Update billing to continue.`);
    this.name = "WorkspaceLockedError";
  }
}

/** The pure lock rule, evaluated against the subscription as stored. */
export function lockReasonFor(
  subscription: Subscription | null,
  now: Date = new Date(),
): WorkspaceLockReason | null {
  if (!subscription) return null;
  const t = now.getTime();
  switch (subscription.status) {
    case "past_due":
      return "past_due";
    case "trialing":
      return t >= new Date(subscription.currentPeriodEnd).getTime()
        ? "trial_ended"
        : null;
    case "canceled":
      return subscription.cancelAt === null ||
        t >= new Date(subscription.cancelAt).getTime()
        ? "canceled"
        : null;
    default:
      return null;
  }
}
EOF
